from __future__ import annotations

from typing import Generator, Any, Set, Callable, List, Dict

from weakref import ref

# from weakref import WeakSet as wrWeakSet
from weakref import ReferenceType as wrReferenceType

from phoenix.fgen.instruction import Instruction
from phoenix.fgen.libroutinevar import LibRoutineVariable


__doc__ = """
CodeContainer module description

"""

# you cannot change your parents once you're born
ALLOW_FOSTER_PARENTING = False


class CodeContainer:
    """
    A Codecontainer is a fundamental building block in the code that is
    ultimately generated. This is the internal base class that includes
    anything that is not yet language specific.

    """

    _IND = "  "
    _REQUEST_KEYS: List[str] = []
    _KEY_DEFAULTS: Dict[str, Any] = {}

    def __init__(self, parent=None, **params) -> None:
        # all content that may or may not be useful
        self._params = params

        # collect variables that are used here
        self._requirements: Set[LibRoutineVariable] = set()

        # content, divided in three sections, head, body, foot
        self._container_head: list[CodeContainer] = []
        self._container_body: list[CodeContainer] = []
        self._container_foot: list[CodeContainer] = []

        # parent link
        self._wr_parent: wrReferenceType[CodeContainer] | None = None
        self._set_parent(parent)  # manage parent reference, might be weak

        # hierarchy level
        if self.parent is None:
            level = 0
        else:
            level = self.parent.level
        self._level = level

    @classmethod
    def from_instruction(cls, instruction: Instruction, level=0, parent=None):
        """request data from instruction, supplement with defaults if valid"""
        return cls(
            level=level,
            parent=parent,
            **instruction.to_dict(*cls._REQUEST_KEYS, cls._KEY_DEFAULTS),
        )

    def _set_parent(self, parent):
        """private method to manage the parent reference"""
        if parent is None:
            self._wr_parent = None
        else:
            self._wr_parent = ref(parent)

    def _get_code_container_lines_head(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        for content in self._container_head:
            yield from content.get_codelines(indent=indent, **kwargs)

    def _get_code_container_lines_body(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        for content in self._container_body:
            yield from content.get_codelines(indent=indent + 1, **kwargs)

    def _get_code_container_lines_foot(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        for content in self._container_foot:
            yield from content.get_codelines(indent=indent, **kwargs)

    def get_codelines(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        """get the codelines from the container"""
        yield from self._get_code_container_lines_head(indent, **kwargs)
        yield from self._get_code_container_lines_body(indent, **kwargs)
        yield from self._get_code_container_lines_foot(indent, **kwargs)

    @property
    def level(self):
        """access the level but prohibit setting it manually"""
        return self._level

    @property
    def parent(self) -> CodeContainer | None:
        """access the parent"""
        if self._wr_parent is None:
            return None
        if (parent := self._wr_parent()) is None:
            raise ValueError("Parent has been garbage collected")
        return parent

    @parent.setter
    def parent(self, parent: CodeContainer) -> None:
        """safe-set parent, IF ALLOWED"""
        if not ALLOW_FOSTER_PARENTING:
            raise RuntimeError("The Lord does not allow that!")
        if self._wr_parent is None:
            if isinstance(parent, CodeContainer):
                self._wr_parent = ref(parent)
        else:
            raise ValueError("Parent already set")

    @property
    def content(self):
        """iterate through content"""
        yield from self._container_head
        yield from self._container_body
        yield from self._container_foot

    @property
    def body(self):
        """iterate through body content only"""
        yield from self._container_body

    def update_requirements(
        self,
    ) -> Generator[LibRoutineVariable, None, None]:
        """iterate over all possible requirements. Eliminate duplicates"""
        known = set()
        for cont in self.content:
            for requirement in cont.update_requirements():
                if requirement not in known:
                    known.add(requirement)
                    yield requirement

    def reset_provided_requirements(self) -> None:
        """reset the provided requirements"""
        for content in self.content:
            content.reset_provided_requirements()

    def append_head(self, *containers: CodeContainer) -> None:
        """append at head"""
        for container in containers:
            self._container_head.append(container)

    def append_body(self, *containers: CodeContainer) -> None:
        """append at body"""
        for container in containers:
            self._container_body.append(container)

    def append_foot(self, *containers: CodeContainer) -> None:
        """append at foot"""
        for container in containers:
            self._container_foot.append(container)

    def requires(self, requirement: LibRoutineVariable) -> None:
        """add a requirement to the codeblock"""
        if not isinstance(requirement, LibRoutineVariable):
            raise TypeError("Dependencies must be LibRoutineVariables")
        self._requirements.add(requirement)

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        # if not overwritten, generic CodeContainers do not captere anything
        return False

    # provide routines for multiline comments and lists
    @staticmethod
    def multiline_list(
        list_of_strings,
        separator=", ",
        max_line_length=100,
        indent="",
        extra_indent="  ",
        linebreak="",
        lbracket="[",
        rbracket="]",
        separate_brackets=False,
    ):
        """create a multiline list for nice output"""
        lines = []
        string_line = ""
        is_first = True
        if separate_brackets:
            if lbracket:
                lines.append(indent + lbracket)
        for string in list_of_strings:
            if separate_brackets:
                if lbracket:
                    extra = extra_indent
            else:
                extra = lbracket if is_first else extra_indent
            if is_first:
                if len(indent + extra + string) <= (max_line_length):
                    string_line = indent + extra + string
                    is_first = False
                else:
                    raise ValueError("line too long!")
            else:
                if len(string_line + separator + string) <= max_line_length:
                    string_line += separator + string

                else:
                    lines.append(string_line + separator)
                    string_line = indent + extra + string
                    is_first = False

        if separate_brackets:
            if string_line:
                lines.append(string_line)
            if rbracket:
                lines.append(indent + rbracket)
        else:
            if rbracket:
                if len(string_line + rbracket) <= max_line_length:
                    lines.append(string_line + rbracket)
                else:
                    lines.append(string_line)
                    lines.append(indent + extra + rbracket)
            else:
                if string_line:
                    lines.append(string_line)

        return f"{linebreak}\n".join(lines)

    @staticmethod
    def multiline_text(
        large_text,
        max_line_length=80,
        indent="",
        extra_indent="  ",
        linebreak="",
    ):
        """create multiline text"""
        return CodeContainer.multiline_list(large_text.split(" "), " ")


class DefinitionSection(CodeContainer):
    """
    A code container that defines stuff and prevents them from getting passed
    on during requirement iterator. Supports a filtering function that decides
    on which type of requirements are implemented here or passed on.
    """

    def __init__(self, **params) -> None:
        super().__init__(**params)
        self._filter_func_customs: Set[Callable] = set()
        self._filter_func_captures: Set[str] = set()
        self._provide: Set[LibRoutineVariable] = set()

    def add_capture(self, capture: str | Callable) -> None:
        """add a type of requirement to capture"""
        if isinstance(capture, str):
            self._filter_func_captures.add(capture)
        elif callable(capture):
            self._filter_func_customs.add(capture)
        else:
            raise ValueError(
                f"Invalid filter arg {capture}. Must be str|callable."
            )

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        for func in self._filter_func_customs:
            if func(requirement):
                return True
        if requirement.vtype in self._filter_func_captures:
            return True
        return False

    def reset_provided_requirements(self):
        for content in self.content:
            content.reset_provided()
        self._provide = set()

    def update_requirements(
        self,
    ) -> Generator[LibRoutineVariable, None, None]:
        """As parent, but keep the requirements that the filter catches"""
        for requirement in super().update_requirements():
            if self.capture_check(requirement):
                self._provide.add(requirement)
            else:
                yield requirement


class RoutineDefinition(DefinitionSection):
    """
    How a routine is defined, with its arguments, definitions, body, ...
    """

    def __init__(self, **params) -> None:
        super().__init__(**params)
        self.add_capture("INPUT")
        self.add_capture("OUTPUT")


class LibraryContainer(DefinitionSection):
    """
    A Library contains routines, constants and more
    """

    def __init__(self, **params) -> None:
        super().__init__(**params)

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        # library level must capture all required variables!
        if not requirement.vtype == "CONSTANT":
            raise ValueError(
                "only constants are allowed to traverse to library definition level"
            )
        return True


class CodeLine(CodeContainer):
    """Recursion-Breaking."""


class StatementLine(CodeLine):
    """
    A statement of form
      output = somefunction(input1, ...)
      output = input[index]
      output = input
      output = input1 some_operator input2

    Serves as base class for more specific statements
    """


class CommentLine(CodeLine):
    """
    A statement of form
      output = somefunction(input1, ...)
      output = input[index]
      output = input
      output = input1 some_operator input2

    Serves as base class for more specific statements
    """


if __name__ == "__main__":
    from phoenix.fgen.libroutinevar import (
        LibRoutineConstant,
        LibRoutineLocalVariable,
    )

    foo = DefinitionSection()
    print(foo.capture_check(LibRoutineConstant("foo", 1337, 42)))  # False
    foo.add_capture("CONSTANT")
    print(foo.capture_check(LibRoutineConstant("foo", 1337, 42)))  # True
    print()
    print(foo.capture_check(LibRoutineLocalVariable("foo")))  # False
    foo.add_capture("LOCAL")
    print(foo.capture_check(LibRoutineLocalVariable("foo")))  # True
    print()
    print(foo.capture_check(LibRoutineVariable("foo", 1337)))  # False
    foo.add_capture(lambda x: x.size > 1)
    print(foo.capture_check(LibRoutineVariable("foo", 1337)))  # True
    print()
    print(foo.capture_check(LibRoutineVariable("foo", 1)))  # False
    foo.add_capture(lambda x: "f" in x.name)
    print(foo.capture_check(LibRoutineVariable("foo", 1)))  # True


SUMMARY = """
Definition section provides capture capability.
Builder has mapping from instruction type to class. CRO is analyzed to find
most specific fit among supported codecontainers.

CodeLines do not contain other containers and break any recursion. In the end,
anything is broken down into codelines, where indentation is handled.

I give up on the idea, that code containers are made from instruction. The
assignment between instruction types and codecontainer subclasses is made by
the Builder instance and only preceding Optimizers can influence the ultimate
instruction tree.
"""
print(SUMMARY)


print(
    CodeContainer.multiline_list(
        ["Hello", "World!", "Foo", "Bar", "Baz"],
        "|",
        max_line_length=13,
        indent="    ",
    )
)
